UPDATE skills s SET category = COALESCE(s.category, v.category), description = COALESCE(s.description, v.description)
FROM (VALUES
  ('Bond Pull and Shear Testing', 'Quality & Measurement', 'Checking wire bond and die attach strength with pull and shear tests'),
  ('Destructive Weld Testing', 'Quality & Measurement', 'Proving weld strength by peel, chisel, bend or pull tests and cut sections'),
  ('Electrical Fault Isolation', 'Quality & Measurement', 'Localizing a failure site in a device from its electrical behavior before physical analysis'),
  ('Endpoint Detection', 'Quality & Measurement', 'Setting up and reading the signals that tell an etch or polish step when to stop'),
  ('Fault Detection and Classification', 'Quality & Measurement', 'Monitoring tool sensor traces to catch and classify process excursions'),
  ('Laser Safety', 'Quality & Measurement', 'Working safely around industrial lasers: enclosures, interlocks and eyewear'),
  ('Residual Gas Analysis', 'Quality & Measurement', 'Reading a residual gas analyzer to find leaks and contamination in a vacuum chamber'),
  ('Wafer Map Analysis', 'Quality & Measurement', 'Reading wafer maps and bin patterns to trace yield loss to its source')
) AS v(name, category, description)
WHERE s.name = v.name AND (s.category IS NULL OR s.description IS NULL);

